drop policy if exists "Matched businesses view their leads" on public.leads; create or replace function public.get_business_opportunities(target_match_id uuid default null) returns table(match_id uuid,lead_id uuid,business_id uuid,match_score numeric(5,2),match_status public.match_status,matched_at timestamptz,viewed_at timestamptz,interested_at timestamptz,connected_at timestamptz,resolved_at timestamptz,plan_title text,plan_description text,budget_range public.budget_range,timeline public.project_timeline,city_name text,category_names text[],contact_name text,contact_email text,contact_phone text) language sql stable security definer set search_path=public as $$ select lm.id,lm.lead_id,lm.business_id,lm.match_score,lm.match_status,lm.created_at,lm.viewed_at,lm.interested_at,lm.connected_at,lm.resolved_at,pp.title,pp.description,pp.budget_range,pp.timeline,c.name,(select array_agg(cat.name order by cat.name) from public.project_plan_categories ppc join public.categories cat on cat.id=ppc.category_id where ppc.plan_id=pp.id),case when lm.match_status in('connected','won','lost') then l.contact_name else null end,case when lm.match_status in('connected','won','lost') then l.contact_email else null end,case when lm.match_status in('connected','won','lost') then l.contact_phone else null end from public.lead_matches lm join public.leads l on l.id=lm.lead_id left join public.project_plans pp on pp.id=l.project_plan_id left join public.cities c on c.id=pp.city_id where public.owns_business(lm.business_id) and (target_match_id is null or lm.id=target_match_id) order by lm.created_at desc; $$; revoke all on function public.get_business_opportunities(uuid) from public; grant execute on function public.get_business_opportunities(uuid) to authenticated;